import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Time-and-Date-Formats.md","filePath":"manual-en/Time-and-Date-Formats.md","lastUpdated":1785684581000}'),i={name:"manual-en/Time-and-Date-Formats.md"};function o(s,t,n,m,p,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h4 id="_6-7-4-5-time-and-date-formats" tabindex="-1">6.7.4.5 Time and Date Formats <a class="header-anchor" href="#_6-7-4-5-time-and-date-formats" aria-label="Permalink to &quot;6.7.4.5 Time and Date Formats&quot;">​</a></h4><p>In PSPP, a <em>time</em> is an interval. The time formats translate between human-friendly descriptions of time intervals and PSPP’s internal representation of time intervals, which is simply the number of seconds in the interval. PSPP has three time formats:</p><table tabindex="0"><thead><tr><th>Time Format</th><th>Template</th><th>Example</th></tr></thead><tbody><tr><td>MTIME</td><td>MM:SS.ss</td><td>91:17.01</td></tr><tr><td>TIME</td><td>hh:MM:SS.ss</td><td>01:31:17.01</td></tr><tr><td>DTIME</td><td>DD HH:MM:SS.ss</td><td>00 04:31:17.01</td></tr></tbody></table><p>A <em>date</em> is a moment in the past or the future. Internally, PSPP represents a date as the number of seconds since the <em>epoch</em> , midnight, Oct. 14, 1582. The date formats translate between human-readable dates and PSPP’s numeric representation of dates and times. PSPP has several date formats:</p><table tabindex="0"><thead><tr><th>Date Format</th><th>Template</th><th>Example</th></tr></thead><tbody><tr><td>DATE</td><td>dd-mmm-yyyy</td><td>01-OCT-1978</td></tr><tr><td>ADATE</td><td>mm/dd/yyyy</td><td>10/01/1978</td></tr><tr><td>EDATE</td><td>dd.mm.yyyy</td><td>01.10.1978</td></tr><tr><td>JDATE</td><td>yyyyjjj</td><td>1978274</td></tr><tr><td>SDATE</td><td>yyyy/mm/dd</td><td>1978/10/01</td></tr><tr><td>QYR</td><td>q Q yyyy</td><td>3 Q 1978</td></tr><tr><td>MOYR</td><td>mmm yyyy</td><td>OCT 1978</td></tr><tr><td>WKYR</td><td>ww WK yyyy</td><td>40 WK 1978</td></tr><tr><td>DATETIME</td><td>dd-mmm-yyyy HH:MM:SS.ss</td><td>01-OCT-1978 04:31:17.01</td></tr><tr><td>YMDHMS</td><td>yyyy-mm-dd HH:MM:SS.ss</td><td>1978-01-OCT 04:31:17.01</td></tr></tbody></table><p>The templates in the preceding tables describe how the time and date formats are input and output:</p><p><code>dd</code></p><p>Day of month, from 1 to 31. Always output as two digits.</p><p><code>mm</code><code>mmm</code></p><p>Month. In output, <code>mm</code> is output as two digits, <code>mmm</code> as the first three letters of an English month name (January, February, …). In input, both of these formats, plus Roman numerals, are accepted.</p><p><code>yyyy</code></p><p>Year. In output, DATETIME and YMDHMS always produce 4-digit years; other formats can produce a 2- or 4-digit year. The century assumed for 2-digit years depends on the EPOCH setting (see <a href="./SET#SET-EPOCH">SET EPOCH</a>). In output, a year outside the epoch causes the whole field to be filled with asterisks (‘*’).</p><p><code>jjj</code></p><p>Day of year (Julian day), from 1 to 366. This is exactly three digits giving the count of days from the start of the year. January 1 is considered day 1.</p><p><code>q</code></p><p>Quarter of year, from 1 to 4. Quarters start on January 1, April 1, July 1, and October 1.</p><p><code>ww</code></p><p>Week of year, from 1 to 53. Output as exactly two digits. January 1 is the first day of week 1.</p><p><code>DD</code></p><p>Count of days, which may be positive or negative. Output as at least two digits.</p><p><code>hh</code></p><p>Count of hours, which may be positive or negative. Output as at least two digits.</p><p><code>HH</code></p><p>Hour of day, from 0 to 23. Output as exactly two digits.</p><p><code>MM</code></p><p>In MTIME, count of minutes, which may be positive or negative. Output as at least two digits.</p><p>In other formats, minute of hour, from 0 to 59. Output as exactly two digits.</p><p><code>SS.ss</code></p><p>Seconds within minute, from 0 to 59. The integer part is output as exactly two digits. On output, seconds and fractional seconds may or may not be included, depending on field width and decimal places. On input, seconds and fractional seconds are optional. The DECIMAL setting controls the character accepted and displayed as the decimal point (see <a href="./SET#SET-DECIMAL">SET DECIMAL</a>).</p><p>For output, the date and time formats use the delimiters indicated in the table. For input, date components may be separated by spaces or by one of the characters ‘-’, ‘/’, ‘.’, or ‘,’, and time components may be separated by spaces or ‘:’. On input, the ‘Q’ separating quarter from year and the ‘WK’ separating week from year may be uppercase or lowercase, and the spaces around them are optional.</p><p>On input, all time and date formats accept any amount of leading and trailing white space.</p><p>The maximum width for time and date formats is 40 columns. Minimum input and output width for each of the time and date formats is shown below:</p><table tabindex="0"><thead><tr><th>Format</th><th>Min. Input Width</th><th>Min. Output Width</th><th>Option</th></tr></thead><tbody><tr><td>DATE</td><td>8</td><td>9</td><td>4-digit year</td></tr><tr><td>ADATE</td><td>8</td><td>8</td><td>4-digit year</td></tr><tr><td>EDATE</td><td>8</td><td>8</td><td>4-digit year</td></tr><tr><td>JDATE</td><td>5</td><td>5</td><td>4-digit year</td></tr><tr><td>SDATE</td><td>8</td><td>8</td><td>4-digit year</td></tr><tr><td>QYR</td><td>4</td><td>6</td><td>4-digit year</td></tr><tr><td>MOYR</td><td>6</td><td>6</td><td>4-digit year</td></tr><tr><td>WKYR</td><td>6</td><td>8</td><td>4-digit year</td></tr><tr><td>DATETIME</td><td>17</td><td>17</td><td>seconds</td></tr><tr><td>YMDHMS</td><td>12</td><td>16</td><td>seconds</td></tr><tr><td>MTIME</td><td>4</td><td>5</td><td></td></tr><tr><td>TIME</td><td>5</td><td>5</td><td>seconds</td></tr><tr><td>DTIME</td><td>8</td><td>8</td><td>seconds</td></tr></tbody></table><p>In the table, “Option” describes what increased output width enables:</p><p>4-digit year</p><p>A field 2 columns wider than the minimum includes a 4-digit year. (DATETIME and YMDHMS formats always include a 4-digit year.)</p><p>seconds</p><p>A field 3 columns wider than the minimum includes seconds as well as minutes. A field 5 columns wider than minimum, or more, can also include a decimal point and fractional seconds (but no more than allowed by the format’s decimal places).</p><p>For the time and date formats, the default output format is the same as the input format, except that PSPP increases the field width, if necessary, to the minimum allowed for output.</p><p>Time or dates narrower than the field width are right-justified within the field.</p><p>When a time or date exceeds the field width, characters are trimmed from the end until it fits. This can occur in an unusual situation, <em>e.g.</em> with a year greater than 9999 (which adds an extra digit), or for a negative value on MTIME, TIME, or DTIME (which adds a leading minus sign).</p><p>The system-missing value is output as a period at the right end of the field.</p>',42)])])}const l=e(i,[["render",o]]);export{u as __pageData,l as default};
